#!/usr/bin/env node
'use strict';
const fs=require('node:fs'),path=require('node:path'),zlib=require('node:zlib');const root=path.resolve(__dirname,'..'),b=fs.readFileSync(path.join(root,'scripts/build.js'),'utf8'),m=b.slice(b.indexOf('const GROUP_A = ['),b.indexOf('const ALL_SOURCE = [...GROUP_A, ...GROUP_B];')),files=[...m.matchAll(/'([^']+\.js)'/g)].map(x=>x[1]);const rows=files.map(f=>({f,n:fs.statSync(path.join(root,f)).size,group:m.indexOf(`'${f}'`)<m.indexOf('const GROUP_B = [')?'A':'B'})).sort((a,b)=>b.n-a.n);for(const g of ['A','B']){const r=rows.filter(x=>x.group===g);console.log(`GROUP_${g}: ${r.length} files, ${r.reduce((a,x)=>a+x.n,0)} source bytes`)}console.log('TOP 20 FILES');rows.slice(0,20).forEach(x=>console.log(`${x.n}\t${x.f}`));let total=0;for(const f of ['app-bundle-a.min.js','app-bundle-b.min.js']){const d=fs.readFileSync(path.join(root,f));total+=zlib.gzipSync(d).length;console.log(`${f}: minified=${d.length} gzip=${zlib.gzipSync(d).length}`)}console.log(`GZIP_TOTAL=${total} WARNING_BUDGET=${Math.ceil(total*1.1)}`);
